 static NativeFlatWallBlock block(){var id=ResourceLocation.fromNamespaceAndPath("vandorlabs","programmable_porthole_block");need(BuiltInRegistries.BLOCK.containsKey(id),"canonical block registered (no AIR fallback)");var block=BuiltInRegistries.BLOCK.get(id);need(block instanceof NativeFlatWallBlock&&((NativeFlatWallBlock)block).isPorthole()&&((NativeFlatWallBlock)block).isFullDepth(),"real full-depth profile");return (NativeFlatWallBlock)block;}
